<span class="line"><span style="color:#C678DD;">    access_log </span><span style="color:#ABB2BF;">/var/log/nginx/access_sample.log </span><span style="color:#D19A66;">main</span><span style="color:#ABB2BF;"> if=$</span><span style="color:#E06C75;">log_sample_16</span><span style="color:#ABB2BF;">;</span></span>
