<span class="line"><span style="color:#E5C07B;">    stats</span><span style="color:#ABB2BF;">:</span><span style="color:#61AFEF;">incr</span><span style="color:#ABB2BF;">(</span><span style="color:#E06C75;">uri_key</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">)</span></span>
